global.auditIndex=0;global.auditRecords=[];global.tipRecords=[];
global.scanView=async(label,page=p)=>{const info=await page.evaluate(()=>{const visible=e=>{const r=e.getBoundingClientRect(),s=getComputedStyle(e);return r.width>0&&r.height>0&&s.display!=='none'&&s.visibility!=='hidden'};const attrs=Array.from(document.querySelectorAll('body *')).filter(visible).flatMap(e=>['title','placeholder','aria-label'].filter(a=>e.getAttribute(a)).map(a=>({tag:e.tagName,id:e.id,attribute:a,text:e.getAttribute(a)})));return{title:document.title,url:location.href,active:document.querySelector('section.panel.active')?.id,viewport:{width:innerWidth,height:innerHeight},scrollY,body:document.body.innerText,attributes:attrs}});const terms=/(?:S4|M[0-9]|SQLite)/ig;const hits=[];for(const [origin,text]of [['body',info.body],...info.attributes.map(a=>[a.id+':'+a.attribute,a.text])]){let m;while((m=terms.exec(text))!==null)hits.push({origin,term:m[0],context:text.slice(Math.max(0,m.index-65),m.index+100)});}const rec={label,time:new Date().toISOString(),...info,hits};auditRecords.push(rec);fs.writeFileSync(root+'copy-audit.json',JSON.stringify(auditRecords,null,2));log('copy-audit',{label,hits});await verify('COPY no internal development terms '+label,hits.length,0);return rec;};
global.auditTips=async(label,page=p)=>{const before=(await snap(page)).state;const buttons=await page.locator('section.panel.active .srm-hint-button:visible').evaluateAll(es=>es.map(e=>({id:e.getAttribute('aria-controls'),label:e.getAttribute('aria-label')})));for(const [i,b]of buttons.entries()){const button=page.locator('[aria-controls="'+b.id+'"]');if(!await button.isVisible())continue;await button.scrollIntoViewIfNeeded();await button.hover();const pop=page.locator('#'+b.id);await expect(pop).toBeVisible();const v=await pop.evaluate(e=>{const r=e.getBoundingClientRect();return{text:e.innerText,top:r.top,bottom:r.bottom,left:r.left,right:r.right,width:r.width,height:r.height,viewport:{width:innerWidth,height:innerHeight},overflowAncestors:Array.from((function*(n){while(n=n.parentElement)yield n})(e)).filter(a=>/hidden|clip/.test(getComputedStyle(a).overflow+getComputedStyle(a).overflowY+getComputedStyle(a).overflowX)).map(a=>({tag:a.tagName,id:a.id,overflow:getComputedStyle(a).overflow,box:a.getBoundingClientRect().toJSON()}))}});const r={label,id:b.id,controlLabel:b.label,...v,terms:v.text.match(/S4|M[0-9]|SQLite/ig)||[]};tipRecords.push(r);log('tooltip-audit',r);if(i===0||r.terms.length||r.left<0||r.right>v.viewport.width||r.bottom>v.viewport.height)await shot('TIP-'+(++auditIndex)+'-'+label,page);await verify('COPY tooltip no internal terms '+b.id,r.terms.length,0);await page.mouse.move(1,1);await button.blur();}
fs.writeFileSync(root+'tooltip-audit.json',JSON.stringify(tipRecords,null,2));await check('Tooltips preserve actual business state '+label,(await snap(page)).state,before);};
global.auditPages=async(stage,withTips=true)=>{for(const page of ['project','items','assign','quoteImport','quotes','backup']){await nav(page);await p.evaluate(()=>window.scrollTo(0,0));await scanView(stage+'-'+page);await shot('PAGE-'+stage+'-'+page);if(withTips)await auditTips(stage+'-'+page);}await nav('project');log('scope-complete',{id:'COPY-'+stage,status:'executed; audit verdict in copy/tooltip records'});};
